async function createShare(kind,target,permission='edit',forceNew=false){await hold();if(kind==='folder'&&!forceNew){shareTarget={kind,target};$('share-heading').textContent='Chia sẻ thư mục · '+target;$('share-result').hidden=false;$('share-new-link').hidden=true;$('share-url').value='';$('share-copy-status').textContent='';$('all-shares').textContent='Đang tải liên kết…';const links=await loadShares(kind,target);if(!authenticated||!Array.isArray(links))return;if(links.length){const field=$('all-shares').querySelector('input[aria-label="Liên kết chia sẻ"]');if(field){const message=field.closest('.share-link-tools').querySelector('[role="status"]');await copyShareLink(field.value,field,message,'Đã chia sẻ. Link đã được sao chép vào clipboard.');}else status('Thư mục đã được chia sẻ. Link cũ vẫn hoạt động; hãy tạo link mới để sao chép lại.');$('share-result').scrollIntoView({block:'nearest'});return;}}
 const r=await api('note-share',{method:'POST',data:{action:'create',permission,...(kind==='folder'?{folder:target}:{noteId:target})}});if(!authenticated)return;shareTarget={kind,target};$('share-heading').textContent=kind==='folder'?'Chia sẻ thư mục · '+target:'Chia sẻ Note';$('share-new-link').hidden=false;$('share-url').value=location.origin+'/#'+kind+'='+r.token;$('share-copy-status').textContent='';$('share-result').hidden=false;$('all-shares').replaceChildren();const copied=kind==='folder'?await copyShareLink($('share-url').value,$('share-url'),$('share-copy-status'),'Đã chia sẻ. Link đã được sao chép vào clipboard.'):false;await loadShares(kind,target);if(kind==='folder'&&copied){$('share-new-link').hidden=true;const field=$('all-shares').querySelector('input[aria-label="Liên kết chia sẻ"]'),message=field?.closest('.share-link-tools').querySelector('[role="status"]');if(message)message.textContent='Đã chia sẻ. Link đã được sao chép vào clipboard.';}$('share-result').scrollIntoView({block:'nearest'});}
