// The native textarea paste path can synchronously reflow large clipboard
// payloads before returning. Insert plain text once, then enter the normal
// input/draft/autosave path once. Keep a bounded inverse for native Ctrl/Cmd+Z.
const pasteUndo=[];function undoPaste(){const item=pasteUndo.pop();if(!item)return;const el=$('text');el.setRangeText(item.replaced,item.start,item.start+item.inserted.length,'select');el.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'historyUndo',data:null}));}
